class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def reverseList(head: ListNode) -> ListNode:
    prev = None
    cur = head
    while cur:
        nxt = cur.next      # 1) 暂存后继
        cur.next = prev     # 2) 反向
        prev = cur          # 3) 推进
        cur = nxt
    return prev
